import{_ as i,c as e,o as r,ag as l}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/faq.md","filePath":"zh-CN/guide/faq.md","lastUpdated":1794112334000}'),t={name:"zh-CN/guide/faq.md"};function o(s,a,h,c,n,d){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="通用问题" tabindex="-1">通用问题 <a class="header-anchor" href="#通用问题" aria-label="Permalink to &quot;通用问题&quot;">​</a></h2><h3 id="nicasa-是什么" tabindex="-1">Nicasa 是什么？ <a class="header-anchor" href="#nicasa-是什么" aria-label="Permalink to &quot;Nicasa 是什么？&quot;">​</a></h3><p>Nicasa 是一款专为 macOS 打造的现代桌面图片查看与截图工具。它以干净、响应迅速的界面提供快速直观的图片浏览，并具备强大的 AI 编辑能力。</p><h3 id="nicasa-免费吗" tabindex="-1">Nicasa 免费吗？ <a class="header-anchor" href="#nicasa-免费吗" aria-label="Permalink to &quot;Nicasa 免费吗？&quot;">​</a></h3><p>Chrome 扩展完全免费，可随意下载使用。macOS 应用需一次性支付 $4.99，才能解锁全部功能。</p><h3 id="支持哪些操作系统" tabindex="-1">支持哪些操作系统？ <a class="header-anchor" href="#支持哪些操作系统" aria-label="Permalink to &quot;支持哪些操作系统？&quot;">​</a></h3><p>Nicasa 目前仅支持 macOS 10.13 或更高版本，暂不提供 Windows 与 Linux 版本。</p><h3 id="如何更新-nicasa" tabindex="-1">如何更新 Nicasa？ <a class="header-anchor" href="#如何更新-nicasa" aria-label="Permalink to &quot;如何更新 Nicasa？&quot;">​</a></h3><p>更新通过 Mac App Store 进行。有新版本时会收到通知，也可以直接在 App Store 应用中更新。</p><h2 id="使用问题" tabindex="-1">使用问题 <a class="header-anchor" href="#使用问题" aria-label="Permalink to &quot;使用问题&quot;">​</a></h2><h3 id="如何用-nicasa-截图" tabindex="-1">如何用 Nicasa 截图？ <a class="header-anchor" href="#如何用-nicasa-截图" aria-label="Permalink to &quot;如何用 Nicasa 截图？&quot;">​</a></h3><ol><li>启动 Nicasa</li><li>点击工具栏中的截图按钮，或使用 <code>Cmd+S</code></li><li>选择你想要截取的区域</li><li>截图会在 Nicasa 中打开，可立即编辑</li></ol><h3 id="nicasa-能处理网页图片吗" tabindex="-1">Nicasa 能处理网页图片吗？ <a class="header-anchor" href="#nicasa-能处理网页图片吗" aria-label="Permalink to &quot;Nicasa 能处理网页图片吗？&quot;">​</a></h3><p>可以！安装免费的 Nicasa Chrome 扩展即可：</p><ul><li>在一个地方查看任意网站的所有图片</li><li>随时提取并浏览图片</li><li>直接在 Nicasa 中打开图片，获得更好的查看体验</li></ul><h3 id="有哪些-ai-编辑功能" tabindex="-1">有哪些 AI 编辑功能？ <a class="header-anchor" href="#有哪些-ai-编辑功能" aria-label="Permalink to &quot;有哪些 AI 编辑功能？&quot;">​</a></h3><p>Nicasa 内置强大的 AI 工具：</p><ul><li><strong>自动增强</strong>：自动提升画质</li><li><strong>智能裁剪</strong>：智能裁剪建议</li><li><strong>图像修复</strong>：智能去除不需要的物体</li><li><strong>色彩校正</strong>：由 AI 驱动的色彩调整</li><li><strong>降噪</strong>：去除噪点与颗粒</li></ul><h3 id="透明悬浮模式是如何工作的" tabindex="-1">透明悬浮模式是如何工作的？ <a class="header-anchor" href="#透明悬浮模式是如何工作的" aria-label="Permalink to &quot;透明悬浮模式是如何工作的？&quot;">​</a></h3><p>为设计师与画师量身打造：</p><ul><li>把图片以可调透明度置顶于所有窗口之上</li><li>可用于描图、参考对照或 UI 比对</li><li>在所有应用中保持位置不变</li></ul><h2 id="技术问题" tabindex="-1">技术问题 <a class="header-anchor" href="#技术问题" aria-label="Permalink to &quot;技术问题&quot;">​</a></h2><h3 id="为什么需要授予屏幕录制权限" tabindex="-1">为什么需要授予屏幕录制权限？ <a class="header-anchor" href="#为什么需要授予屏幕录制权限" aria-label="Permalink to &quot;为什么需要授予屏幕录制权限？&quot;">​</a></h3><p>截图功能需要屏幕录制权限，这样 Nicasa 才能在你使用截图工具时捕捉屏幕。</p><h3 id="可以离线使用-nicasa-吗" tabindex="-1">可以离线使用 Nicasa 吗？ <a class="header-anchor" href="#可以离线使用-nicasa-吗" aria-label="Permalink to &quot;可以离线使用 Nicasa 吗？&quot;">​</a></h3><p>可以。macOS 应用可完全离线处理本地图片文件；通过 Chrome 扩展提取网页图片则需要网络连接。</p><h3 id="支持哪些-macos-版本" tabindex="-1">支持哪些 macOS 版本？ <a class="header-anchor" href="#支持哪些-macos-版本" aria-label="Permalink to &quot;支持哪些 macOS 版本？&quot;">​</a></h3><p>Nicasa 支持 macOS 10.13 或更高版本，并针对 Apple 芯片优化，在 M 系列芯片上原生运行。</p><h3 id="chrome-扩展需要哪些权限" tabindex="-1">Chrome 扩展需要哪些权限？ <a class="header-anchor" href="#chrome-扩展需要哪些权限" aria-label="Permalink to &quot;Chrome 扩展需要哪些权限？&quot;">​</a></h3><p>该扩展仅为提取图片地址而请求读取页面内容，不会读取或存储浏览记录。</p><h3 id="我的数据会被上传吗" tabindex="-1">我的数据会被上传吗？ <a class="header-anchor" href="#我的数据会被上传吗" aria-label="Permalink to &quot;我的数据会被上传吗？&quot;">​</a></h3><p>不会。所有处理都在你的设备本地完成，Nicasa 不会收集、传输或存储你的图片。</p><h3 id="如何备份我的设置" tabindex="-1">如何备份我的设置？ <a class="header-anchor" href="#如何备份我的设置" aria-label="Permalink to &quot;如何备份我的设置？&quot;">​</a></h3><p>设置保存在本地。备份方法：</p><ol><li>进入 Nicasa &gt; 偏好设置</li><li>如支持，导出你的设置</li><li>或手动备份应用偏好设置文件夹</li></ol><p>设置存储在应用数据文件夹中，复制该文件夹即可完成备份。</p><h3 id="有便携版吗" tabindex="-1">有便携版吗？ <a class="header-anchor" href="#有便携版吗" aria-label="Permalink to &quot;有便携版吗？&quot;">​</a></h3><p>Windows 版本提供便携版，可从我们的网站下载。</p><h2 id="开发问题" tabindex="-1">开发问题 <a class="header-anchor" href="#开发问题" aria-label="Permalink to &quot;开发问题&quot;">​</a></h2><h3 id="我可以为-nicasa-贡献代码吗" tabindex="-1">我可以为 Nicasa 贡献代码吗？ <a class="header-anchor" href="#我可以为-nicasa-贡献代码吗" aria-label="Permalink to &quot;我可以为 Nicasa 贡献代码吗？&quot;">​</a></h3><p>访问我们的 <a href="https://github.com/nicasa-project/nicasa-support" target="_blank" rel="noreferrer">GitHub 仓库</a>，贡献代码、反馈问题或提出功能建议。</p><h3 id="如何从源码构建-nicasa" tabindex="-1">如何从源码构建 Nicasa？ <a class="header-anchor" href="#如何从源码构建-nicasa" aria-label="Permalink to &quot;如何从源码构建 Nicasa？&quot;">​</a></h3><p>请参阅 GitHub 上的开发者文档以获取构建说明。</p><h3 id="nicasa-使用了哪些技术" tabindex="-1">Nicasa 使用了哪些技术？ <a class="header-anchor" href="#nicasa-使用了哪些技术" aria-label="Permalink to &quot;Nicasa 使用了哪些技术？&quot;">​</a></h3><p>Nicasa 使用现代 Web 技术构建，桌面端封装使用 Electron，界面使用 Vue.js。</p><h2 id="隐私问题" tabindex="-1">隐私问题 <a class="header-anchor" href="#隐私问题" aria-label="Permalink to &quot;隐私问题&quot;">​</a></h2><h3 id="nicasa-会收集任何数据吗" tabindex="-1">Nicasa 会收集任何数据吗？ <a class="header-anchor" href="#nicasa-会收集任何数据吗" aria-label="Permalink to &quot;Nicasa 会收集任何数据吗？&quot;">​</a></h3><p>不会。Nicasa 不收集也不传输任何个人数据，所有图片处理都在你的设备本地完成。</p><h3 id="我的图片安全吗" tabindex="-1">我的图片安全吗？ <a class="header-anchor" href="#我的图片安全吗" aria-label="Permalink to &quot;我的图片安全吗？&quot;">​</a></h3><p>安全。Nicasa 只会访问你主动打开的图片，不会上传或分享你的文件。</p><h3 id="nicasa-需要哪些权限" tabindex="-1">Nicasa 需要哪些权限？ <a class="header-anchor" href="#nicasa-需要哪些权限" aria-label="Permalink to &quot;Nicasa 需要哪些权限？&quot;">​</a></h3><p>Nicasa 需要访问文件系统以读取图片和保存设置，运行时不依赖网络。</p><h2 id="还有疑问" tabindex="-1">还有疑问？ <a class="header-anchor" href="#还有疑问" aria-label="Permalink to &quot;还有疑问？&quot;">​</a></h2><p>如果在这里找不到答案，请：</p><ol><li>查阅我们的<a href="/zh-CN/">完整文档</a></li><li>搜索我们的 <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub issues</a></li><li>如有需要，新建一个 issue</li></ol><p>我们随时为你提供帮助！</p>',57)])])}const b=i(t,[["render",o]]);export{p as __pageData,b as default};
